/* Browser-only prototype. No host operations, credentials, or backend requests. */
(() => {
  'use strict';
  const D = window.SENTINEL_DATA;
  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const number = value => new Intl.NumberFormat('en-US').format(value);
  const state = {page:'overview', group:'all', search:'', status:'all', risk:'all', tags:[], assetPage:1, pageSize:10, selected:new Set(), hostTab:'overview', hideLoopback:true, portType:'all', range:'24h', metric:'cpu', findingState:'present', findingSeverity:'all', findingSearch:'', taskState:'all', modal:null, formAssets:[], version:1, sort:'risk'};
  let returnFocus = null;
  let toastTimer;
  const icons = {
    shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8.5 11.5 2.4 2.4 4.8-5"/>',
    grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
    server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01M15 6.5h3M15 17.5h3"/>',
    bug:'<rect x="7" y="7" width="10" height="13" rx="5"/><path d="m9 4 1 3m5-3-1 3M3 10h4m10 0h4M3 15h4m10 0h4m-13 6 3-4m10 4-3-4M12 8v12"/>',
    checklist:'<rect x="5" y="4" width="15" height="17" rx="2"/><path d="M9 4V2h7v2M9 9l1 1 2-2m2 1h3m-8 6 1 1 2-2m2 1h3"/>',
    pulse:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',
    sliders:'<path d="M4 4v4m0 4v8m8-16v9m0 4v3m8-16v2m0 4v10M1 8h6m2 9h6m2-11h6"/>',
    upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',
    logs:'<path d="M8 3h10a2 2 0 0 1 2 2v16H6a2 2 0 0 1-2-2V7h4zM8 3v14H4m8-9h5m-5 4h5"/>',
    search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',
    chevron:'<path d="m9 5 7 7-7 7"/>',
    down:'<path d="m6 9 6 6 6-6"/>',
    left:'<path d="m15 5-7 7 7 7"/>',
    close:'<path d="m6 6 12 12M6 18 18 6"/>',
    bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
    globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 2M5 16a8 8 0 0 0 13 2"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
    alert:'<path d="m12 3 10 18H2zM12 9v5m0 3h.01"/>',
    activity:'<path d="M3 20h18M5 16V9m7 7V4m7 12v-5"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
    folder:'<path d="M3 7V4h6l3 3h9v13H3z"/>',
    cpu:'<rect x="6" y="6" width="12" height="12" rx="2"/><rect x="9" y="9" width="6" height="6" rx="1"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/>',
    network:'<rect x="8" y="2" width="8" height="6" rx="1"/><rect x="2" y="16" width="7" height="6" rx="1"/><rect x="15" y="16" width="7" height="6" rx="1"/><path d="M12 8v4m-7 4v-4h14v4"/>',
    memory:'<rect x="2" y="6" width="20" height="12" rx="1"/><path d="M6 9h3v5H6zm9 0h3v5h-3zM6 18v3m4-3v3m4-3v3m4-3v3"/>',
    spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4m-2-2h4"/>',
    copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
    book:'<path d="M12 5C8 2 4 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-2-1-6-2-10 1zm0 0v16"/>'
  };
  const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.info}</svg>`;
  const button = (label, action, name='', cls='', attributes='') => `<button type="button" class="btn ${cls}" data-action="${action}" ${attributes}>${name ? icon(name):''}${label}</button>`;
  const pill = (label, color='gray', dot=false) => `<span class="pill ${color}">${dot?'<span class="dot"></span>':''}${esc(label)}</span>`;
  const property = (label,value) => `<div><div class="property-label">${esc(label)}</div><div class="property-value">${value}</div></div>`;
  const statusPill = status => pill(({online:'在线',offline:'离线',stale:'数据过期'})[status],({online:'green',offline:'gray',stale:'amber'})[status],true);
  const severityPill = severity => pill(({critical:'严重',high:'高危',medium:'中危',low:'低危',none:'未命中'})[severity] || severity,({critical:'red',high:'amber',medium:'blue',low:'gray',none:'green'})[severity]);
  const taskPill = status => pill(({queued:'待执行',running:'执行中',succeeded:'已完成',failed:'失败',unknown:'结果待确认',cancel_requested:'取消待确认',cancelled:'已取消'})[status]||status,({queued:'gray',running:'blue',succeeded:'green',failed:'red',unknown:'amber',cancel_requested:'amber',cancelled:'gray'})[status],true);
  const verdictPill = verdict => pill(({pass:'通过',fail:'不通过',unknown:'无法确认',error:'执行错误',not_applicable:'不适用'})[verdict]||verdict,({pass:'green',fail:'red',unknown:'amber',error:'red',not_applicable:'gray'})[verdict]);
  const time = iso => new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Singapore',hour12:false}).format(new Date(iso));
  const shortDate = iso => new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Singapore',hour12:false}).format(new Date(iso));
  const asset = id => D.assets.find(a=>a.id===id);
  const scopedAssets = () => D.assets.filter(a=>state.group==='all'||a.group===state.group);
  const scopedFindings = (kind) => { const ids=new Set(scopedAssets().map(a=>a.id)); return D.findings.filter(f=>ids.has(f.assetId)&&(!kind||f.kind===kind)); };
  const metricValue = (a,key,suffix='') => a.metricsStale?'<span title="最近上报已过期">—</span>':`${number(a[key])}${suffix}`;
  const headings = {overview:['安全总览','掌握所有主机的风险、运行状态与检测覆盖。','WORKSPACE OVERVIEW'],assets:['主机资产','从一台主机到整个集群，让每份资产都有迹可循。','ASSET INVENTORY'],vulnerabilities:['漏洞风险','结合软件包清单与发行版情报，追踪每一个风险。','VULNERABILITY MANAGEMENT'],baseline:['配置基线','验证 SSH 与认证配置，保留判断依据与覆盖限制。','CONFIGURATION BASELINE'],tasks:['诊断任务','以只读检查收集证据，跟踪每次执行的完整过程。','INVESTIGATION & TASKS'],policies:['采集策略','定义检查范围、采集频率与资源预算。','POLICY MANAGEMENT'],upgrades:['Scout 升级','按批次发布，观察兼容性与每一次实例交接。','SCOUT RELEASES'],logs:['日志调查','连接跨主机的事件，让调查更有上下文。','LOG EXPLORER']};
  function notify(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
  function renderShell(){
    const present=D.findings.filter(f=>f.kind==='vulnerability'&&f.technicalState==='present').length;
    const nav=(page,label,i,count='')=>`<a href="#/${page}" class="nav-item ${state.page===page?'active':''}" ${state.page===page?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${count}</a>`;
    $('#sidebar').innerHTML=`<a class="brand" href="#/overview" aria-label="Sentinel 总览"><span class="brand-mark">${icon('shield')}</span>Sentinel<sup>HUB</sup></a><div class="workspace-switch"><span class="workspace-icon">${icon('folder')}</span><div class="stack"><strong class="small">基础设施安全</strong><span class="muted" style="font-size:9px">默认工作空间</span></div>${icon('down')}</div><div class="nav-section">工作空间</div><nav class="nav-group">${nav('overview','安全总览','grid')}${nav('assets','主机资产','server',`<span class="nav-count">${number(D.assets.length)}</span>`)}</nav><div class="nav-section">安全中心</div><nav class="nav-group">${nav('vulnerabilities','漏洞风险','bug',`<span class="nav-count alert">${present}</span>`)}${nav('baseline','配置基线','checklist')}${nav('tasks','诊断任务','pulse')}${nav('logs','日志调查','logs','<span class="nav-coming">规划</span>')}</nav><div class="nav-section">管理</div><nav class="nav-group">${nav('policies','采集策略','sliders')}${nav('upgrades','Scout 升级','upload')}</nav><div class="sidebar-bottom"><button type="button" class="nav-item" style="border:0;background:none;width:100%" data-action="about">${icon('book')}原型使用说明</button><div class="system-health"><span class="dot"></span>演示工作空间<span style="margin-left:auto;font-size:9px">v0.1</span></div><div class="user-profile"><span class="avatar">SC</span><div class="stack"><strong style="font-size:11px">Security Admin</strong><span style="font-size:9px;color:#9ba69d">工作空间管理员</span></div>${icon('down')}</div></div>`;
    $('#topbar').innerHTML=`<div class="flex"><button class="icon-button mobile-menu" data-action="menu" aria-label="展开导航" aria-expanded="false" aria-controls="sidebar">${icon('menu')}</button><div class="breadcrumb">${icon('grid')}<span>工作空间</span><span>/</span><strong>${state.hostId&&state.page==='assets'?'主机详情':headings[state.page][0]}</strong></div></div><div class="top-actions"><form id="global-search-form" class="quick-search" role="search">${icon('search')}<input id="global-search" aria-label="全局搜索主机" placeholder="搜索主机、IP 地址…" autocomplete="off"><kbd>⌘ K</kbd></form><span class="top-divider"></span><button class="icon-button" data-action="notifications" aria-label="查看最近动态">${icon('bell')}<span class="notification-dot"></span></button><span class="avatar">SC</span></div>`;
  }
  function pageHeading(actions=''){const h=headings[state.page];return `<div class="page-heading"><div><div class="eyebrow">${h[2]}</div><h1>${h[0]}</h1><p>${h[1]}</p></div><div class="heading-actions">${actions}</div></div>`;}
  function scopebar(){return `<div class="scopebar"><div class="flex"><label class="scope-control">${icon('folder')}<select id="global-group" aria-label="管理组筛选"><option value="all">全部管理组</option>${D.groups.map(g=>`<option ${state.group===g?'selected':''}>${esc(g)}</option>`).join('')}</select></label><label class="scope-control">${icon('clock')}<select id="time-range" aria-label="指标时间范围">${[['24h','最近 24 小时'],['7d','最近 7 天'],['30d','最近 30 天'],['90d','最近 90 天']].map(([v,l])=>`<option value="${v}" ${state.range===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="snapshot-time"><span class="dot"></span><span>快照更新于 ${time(D.snapshotAt)}</span><span class="demo-badge">演示数据</span></div></div>`;}
  function spark(values,color='#7aaa88'){const max=Math.max(...values,1),min=Math.min(...values)-3;return `<svg viewBox="0 0 78 28" preserveAspectRatio="none" aria-hidden="true"><path d="${values.map((v,i)=>`${i?'L':'M'}${i*78/(values.length-1)},${25-(v-min)/(max-min)*21}`).join(' ')}" fill="none" stroke="${color}" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
  function statCard(label,value,i,foot,options={}){return `<div class="stat-card ${options.highlight?'highlight':''}"><div class="stat-label">${label}${icon(i)}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div>${options.spark?`<div class="stat-spark">${spark(options.spark,options.color)}</div>`:''}</div>`;}
  function lineChart(series,{height=180,max=100,labels=['00:00','04:00','08:00','12:00','16:00','20:00','24:00'],large=false}={}){
    const w=640,h=height,l=34,r=10,t=16,b=13,plot=h-t-b;
    const lines=[0,1,2,3].map(k=>{const y=t+k*plot/3;return `<line x1="${l}" x2="${w-r}" y1="${y}" y2="${y}" stroke="#edf1eb" stroke-dasharray="3 4"/><text x="${l-12}" y="${y+3}" text-anchor="end" fill="#a2ada0" font-size="9">${Math.round(max*(1-k/3))}</text>`;}).join('');
    const drawings=series.map((s,j)=>{let gap=true;const points=s.values.map((v,i)=>{if(v===null){gap=true;return '';}const cmd=gap?'M':'L';gap=false;return `${cmd}${l+i*(w-l-r)/(s.values.length-1)},${t+(1-v/max)*plot}`;}).join(' ');return `${s.fill?`<defs><linearGradient id="chart-fill-${j}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${s.color}" stop-opacity=".14"/><stop offset="1" stop-color="${s.color}" stop-opacity="0"/></linearGradient></defs><path d="${points} L${w-r},${h-b} L${l},${h-b} Z" fill="url(#chart-fill-${j})"/>`:''}<path d="${points}" fill="none" stroke="${s.color}" stroke-width="2.1" stroke-linejoin="round" stroke-linecap="round" ${s.dash?'stroke-dasharray="4 4"':''}/>`;}).join('');
    return `<div class="chart-wrap"><svg class="${large?'chart-large':'main-chart'}" role="img" aria-label="${esc(series.map(s=>s.name).join('、'))}趋势，虚构演示数据" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${lines}${drawings}</svg><div class="chart-labels">${labels.map(l=>`<span>${esc(l)}</span>`).join('')}</div></div>`;
  }
  function chartLabels(){return ({'24h':['00:00','04:00','08:00','12:00','16:00','20:00','24:00'],'7d':['10/15','10/16','10/17','10/18','10/19','10/20','10/21'],'30d':['09/22','09/27','10/02','10/07','10/12','10/17','10/21'],'90d':['07/24','08/08','08/23','09/07','09/22','10/07','10/21']})[state.range];}
  function trendValues(base,scale=1){const n=({'24h':1,'7d':1.7,'30d':2.3,'90d':3})[state.range];return Array.from({length:29},(_,i)=>Math.max(1,Math.round(base+(Math.sin(i*.62*n)*2.4+Math.cos(i*.97)*1.5+(i<8?3:0))*scale)));}
  function renderOverview(){
    const list=scopedAssets(),findings=scopedFindings().filter(f=>f.technicalState==='present'),online=list.filter(a=>a.status==='online').length,complete=list.filter(a=>a.coverage==='complete'&&!a.packageSnapshotStale).length,high=findings.filter(f=>['high','critical'].includes(f.severity)).length;
    const counts=['critical','high','medium','low'].map(s=>findings.filter(f=>f.severity===s).length),colors=['#bf7569','#d6a365','#8aab86','#c4d3bd'];let offset=0;
    const donut=counts.map((v,i)=>{const length=v/(findings.length||1)*276.46;const result=`<circle cx="60" cy="60" r="44" fill="none" stroke="${colors[i]}" stroke-width="12" stroke-dasharray="${Math.max(0,length-3)} ${276.46-Math.max(0,length-3)}" stroke-dashoffset="${-offset}"/>`;offset+=length;return result;}).join('');
    const risky=list.filter(a=>a.risk!=='none').sort((a,b)=>riskRank(b.risk)-riskRank(a.risk)).slice(0,5);
    return `${pageHeading(button('导出报告','export-overview','download','')+button('发起检查','new-task','plus','primary'))}${scopebar()}<div class="stat-grid">${statCard('管理主机',number(list.length),'server',`分布在 <span class="green">${new Set(list.map(a=>a.group)).size} 个管理组</span>`,{spark:[9,11,10,13,14,13,16,18]})}${statCard('在线主机',number(online),'pulse',`<span class="green">${list.length?(online/list.length*100).toFixed(1):0}% 在线率</span>`,{spark:[11,12,12,11,14,15,14,15],highlight:true})}${statCard('待处理风险',number(findings.length),'shield',`<span class="red">${high} 项严重 / 高危</span>`,{spark:[18,16,17,13,15,12,11,9],color:'#c9a17c'})}${statCard('完整采集覆盖',`${(complete/(list.length||1)*100).toFixed(1)}<span class="unit">%</span>`,'checklist',`<span>${number(list.length-complete)} 台需关注采集状态</span>`,{spark:[6,7,6,11,10,13,14,14]})}</div>
    <div class="dashboard-row"><section class="panel"><div class="panel-head"><div><h2>风险变化趋势</h2><p>新增与已解决风险 · ${state.range==='24h'?'按小时':'按天'}观察</p></div><div class="chart-legend"><span><i class="legend-square" style="background:#85a47d"></i>已解决</span><span><i class="legend-square" style="background:#c4a176"></i>新增</span></div></div>${lineChart([{name:'已解决风险',values:trendValues(13,2.1),color:'#7e9f74',fill:true},{name:'新增风险',values:trendValues(8,1.1).map((v,i)=>Math.max(1,v+(i%7===0?3:0))),color:'#bfa17c'}],{max:30,labels:chartLabels()})}<div class="chart-summary"><span>当前风险<strong>${findings.length}</strong></span><span>影响主机<strong>${new Set(findings.map(f=>f.assetId)).size} 台</strong></span><span style="margin-left:auto">趋势为演示序列</span></div></section><section class="panel"><div class="panel-head"><div><h2>风险等级分布</h2><p>仅统计当前仍存在的风险</p></div><button class="icon-button" data-action="risk-info" aria-label="风险统计口径">${icon('info')}</button></div><div class="severity-layout"><div class="donut"><svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="44" fill="none" stroke="#f1f4ee" stroke-width="12"/>${donut}</svg><div class="donut-center"><strong>${findings.length}</strong><span>待处理风险</span></div></div><div class="severity-legend">${['严重','高危','中危','低危'].map((l,i)=>`<div class="severity-item"><i class="legend-square" style="background:${colors[i]}"></i>${l}<strong>${counts[i]}</strong></div>`).join('')}</div></div><div class="risk-distribution-note">${icon('info')}接受风险仍计入技术风险，不等于已修复</div></section></div>
    <section class="panel" style="margin-bottom:20px"><div class="panel-head"><div><h2>需要关注的主机 <span class="pill gray">${list.filter(a=>a.risk!=='none').length}</span></h2><p>优先关注高等级风险与运行异常</p></div><a class="link" href="#/assets" data-action="show-risk-assets">查看全部主机 ${icon('arrow')}</a></div>${assetTable(risky,false)}<div class="table-footer"><span>显示风险优先级最高的 ${risky.length} 台主机</span><span class="flex">${icon('shield')}只读检测 · 无自动处置</span></div></section>
    <div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>检测覆盖</h2><a href="#/baseline" class="link">查看基线 ${icon('arrow')}</a></div><div class="coverage-list">${[['资产信息',complete],['软件包清单',complete],['SSH 配置基线',list.filter(a=>!a.baselineUnknown).length]].map(([label,n])=>`<div class="coverage-row"><span>${label}</span><div class="progress-track"><span style="width:${n/(list.length||1)*100}%;background:#9fb995"></span></div><span class="coverage-percent">${(n/(list.length||1)*100).toFixed(1)}%</span></div>`).join('')}</div><div class="coverage-note"><span><i class="legend-square" style="background:#9fb995"></i>完整覆盖</span><span><i class="legend-square" style="background:#eef2e8"></i>未完成 / 无法确认</span></div></section><section class="panel"><div class="panel-head"><h2>最近动态</h2><a class="link" href="#/tasks">任务中心 ${icon('arrow')}</a></div><div class="activity-list">${D.activity.slice(0,3).map(a=>`<div class="activity-row"><div class="activity-icon">${icon(a.type==='warning'?'pulse':'check')}</div><div><p>${esc(a.title)}</p><small>${esc(a.description)}</small></div><time>${a.time}</time></div>`).join('')}</div></section></div>`;
  }
  const riskRank = risk=>({critical:3,high:2,medium:1,none:0})[risk]||0;
  function meter(a,key){return a.metricsStale?'<span class="muted" title="数据过期，未用零代替">—</span>':`<span class="mini-meter"><span class="meter-track"><span class="meter-fill ${a[key]>=85?'hot':a[key]>=65?'warm':''}" style="width:${a[key]}%;display:block"></span></span>${a[key]}%</span>`;}
  function assetTable(list,full=true){return `<div class="table-wrap"><table><thead><tr>${full?'<th style="width:35px"><input type="checkbox" class="table-checkbox" id="select-page" aria-label="选择本页主机"></th>':''}<th>主机名称 / IP</th><th>管理组</th><th>状态</th><th>风险</th><th>CPU</th><th>内存</th>${full?'<th>Scout 版本</th>':''}<th>最近上报</th><th aria-label="操作"></th></tr></thead><tbody>${list.map(a=>`<tr>${full?`<td><input type="checkbox" class="table-checkbox row-select" aria-label="选择 ${a.name}" value="${a.id}" ${state.selected.has(a.id)?'checked':''}></td>`:''}<td><div class="flex"><span class="host-icon">${icon('server')}</span><div><a class="host-name" href="#/assets/${a.id}">${esc(a.name)}</a><div class="host-sub">${esc(a.ip)}</div></div></div></td><td>${esc(a.group)}${full?`<div style="margin-top:4px">${a.tags.filter(t=>t.startsWith('role:')).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`:''}</td><td>${statusPill(a.status)}</td><td>${a.risk==='none'&&a.coverage!=='complete'?pill('覆盖不足','gray'):severityPill(a.risk)}${a.risk!=='none'?`<span class="muted" style="font-size:9px;margin-left:5px">${a.vulnerabilities+a.baselineFailed} 项</span>`:''}</td><td>${meter(a,'cpu')}</td><td>${meter(a,'memory')}</td>${full?`<td class="mono">v${a.version}</td>`:''}<td style="color:#a0aa98;font-size:10px">${a.status==='online'?'刚刚':a.status==='stale'?'32 分钟前':'2 小时前'}</td><td><a href="#/assets/${a.id}" class="icon-button" aria-label="查看 ${a.name}">${icon('chevron')}</a></td></tr>`).join('')||'<tr><td colspan="10"><div class="empty">没有符合筛选条件的主机</div></td></tr>'}</tbody></table></div>`;}
  function filteredAssets(){let list=scopedAssets().filter(a=>(!state.search||[a.name,a.ip,a.id,...a.tags].join(' ').toLowerCase().includes(state.search.toLowerCase()))&&(state.status==='all'||a.status===state.status)&&(state.risk==='all'||(state.risk==='present'?a.risk!=='none':a.risk===state.risk))&&state.tags.every(t=>a.tags.includes(t)));return list.sort(state.sort==='name'?(a,b)=>a.name.localeCompare(b.name):state.sort==='cpu'?(a,b)=>(b.metricsStale?-1:b.cpu)-(a.metricsStale?-1:a.cpu):(a,b)=>riskRank(b.risk)-riskRank(a.risk));}
  function renderAssets(){
    const list=filteredAssets(),pages=Math.max(1,Math.ceil(list.length/state.pageSize));state.assetPage=Math.min(state.assetPage,pages);const visible=list.slice((state.assetPage-1)*state.pageSize,state.assetPage*state.pageSize);
    return `${pageHeading(button('导出资产','export-assets','download')+button('添加主机','enroll','plus','primary'))}${scopebar()}<section class="panel"><div class="filter-toolbar"><div class="flex"><label class="search-box">${icon('search')}<input id="asset-search" aria-label="搜索资产" placeholder="搜索主机名称、IP 或标签" value="${esc(state.search)}"></label><select class="select" id="asset-status" aria-label="在线状态"><option value="all">全部状态</option>${[['online','在线'],['offline','离线'],['stale','数据过期']].map(([v,l])=>`<option value="${v}" ${state.status===v?'selected':''}>${l}</option>`).join('')}</select><select class="select" id="asset-risk" aria-label="风险等级">${[['all','全部风险'],['present','存在风险'],['critical','严重风险'],['high','高危风险'],['none','未命中风险']].map(([v,l])=>`<option value="${v}" ${state.risk===v?'selected':''}>${l}</option>`).join('')}</select></div><select class="select" id="asset-sort" aria-label="资产排序">${[['risk','风险优先'],['name','主机名称'],['cpu','CPU 使用率']].map(([v,l])=>`<option value="${v}" ${state.sort===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="tags-filter" style="padding:0 20px 14px"><span class="muted" style="font-size:10px;margin-right:4px">标签</span>${['tier:critical','role:api','role:db','region:sg-1'].map(t=>`<button class="tag-filter ${state.tags.includes(t)?'active':''}" data-action="tag-filter" data-value="${t}" aria-pressed="${state.tags.includes(t)}">${t}</button>`).join('')}<button class="link" data-action="clear-filters" style="margin-left:auto">重置筛选</button></div>${state.selected.size?`<div class="batch-bar">已选择 ${state.selected.size} 台主机 ${button('发起只读检查','batch-task','pulse','small-btn')}${button('取消选择','clear-selection','','small-btn quiet')}</div>`:''}${assetTable(visible)}<div class="table-footer"><span>共 ${number(list.length)} 台主机 · 第 ${list.length?(state.assetPage-1)*state.pageSize+1:0}–${Math.min(state.assetPage*state.pageSize,list.length)} 台</span><div class="pagination"><button data-action="prev-page" ${state.assetPage===1?'disabled':''} aria-label="上一页">${icon('left')}</button>${Array.from(new Set([1,state.assetPage-1,state.assetPage,state.assetPage+1,pages])).filter(n=>n>0&&n<=pages).sort((a,b)=>a-b).map((n,i,arr)=>`${i&&n-arr[i-1]>1?'<span>…</span>':''}<button data-action="page" data-value="${n}" class="${n===state.assetPage?'active':''}">${n}</button>`).join('')}<button data-action="next-page" ${state.assetPage===pages?'disabled':''} aria-label="下一页">${icon('chevron')}</button></div></div></section>`;
  }
  function renderHost(){
    const a=asset(state.hostId);if(!a)return '<div class="empty"><h2>未找到主机</h2><a href="#/assets" class="btn">返回资产列表</a></div>';
    const tabs=[['overview','运行概况'],['inventory','资产信息'],['packages','软件包与漏洞'],['ports','端口清单'],['baseline','配置基线'],['tasks','任务记录']];
    let body='';
    if(state.hostTab==='overview'){
      body=`<div class="stat-grid">${statCard('CPU 使用率',metricValue(a,'cpu','<span class="unit">%</span>'),'cpu',`${a.cores} 核 · ${a.metricsStale?'最近数据已过期':'宿主机归一化使用率'}`,{spark:a.cpuHistory.slice(-9)})}${statCard('内存使用率',metricValue(a,'memory','<span class="unit">%</span>'),'memory',`总内存 ${a.memoryTotal} GiB · 可用 ${a.metricsStale?'—':(a.memoryTotal*(1-a.memory/100)).toFixed(1)} GiB`)}${statCard('进程数量',metricValue(a,'processes'),'activity','宿主机进程 · 不含线程计数')}${statCard('网卡接收速率',a.metricsStale?'—':`${(a.rxRate/1048576).toFixed(1)}<span class="unit">MiB/s</span>`,'network',`eth0 · 发送 ${a.metricsStale?'—':(a.txRate/1048576).toFixed(1)} MiB/s`)}</div><div class="detail-grid"><section class="panel"><div class="panel-head"><div><h2>资源使用趋势</h2><p>宿主机视图 · ${['24h','7d'].includes(state.range)?'分钟':'小时'}聚合 · 虚构数据</p></div><div class="metric-tabs">${[['cpu','CPU'],['memory','内存']].map(([v,l])=>`<button data-action="metric-tab" data-value="${v}" class="${state.metric===v?'active':''}">${l}</button>`).join('')}</div></div>${lineChart([{name:state.metric==='cpu'?'CPU 使用率':'内存使用率',values:(state.metric==='cpu'?a.cpuHistory:a.memoryHistory).map((v,i)=>a.metricsStale&&i>17?null:v),color:'#7b9f70',fill:!a.metricsStale}],{max:100,large:true,height:210,labels:chartLabels()})}<div class="chart-summary"><span>分钟级保留 7 天</span><span>小时级保留 90 天</span><span style="margin-left:auto">缺测不补零</span></div></section><section class="panel"><div class="panel-head"><h2>采集健康</h2>${a.packageSnapshotStale?pill('清单已过期','amber'):a.coverage==='complete'?pill('完整','green'):pill('覆盖不足','amber')}</div><div class="properties single">${property('最近采集尝试',a.id==='asset-0002'?'<span class="red">10:31 · 采集失败，保留旧结果</span>':a.coverage==='failed'?'08:38 · 失败':a.coverage==='partial'?'10:10 · 部分完成':'10:40 · 已完成')}${property('最近完整结果',`${shortDate(a.packageSnapshotAt)} · ${a.packageSnapshotStale?'清单已过期':'清单完整'}`)}${property('Scout 状态',`v${a.version} · ${a.arch}`)}${property('当前策略',`${a.group==='生产环境'?'生产环境安全基线 · r8':'全局默认策略 · r12'}<br><span class="muted small">期望状态与实际应用分别确认</span>`)}</div></section></div><div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>文件系统容量</h2><span class="muted small">宿主机</span></div><div class="resource-row"><div class="stack"><span class="mono">/</span><span class="muted small">ext4 · /dev/vda1</span></div><div class="stack" style="min-width:150px"><span class="small">${a.metricsStale?'—':a.diskUsed+'%'} 已使用</span><div class="progress-track"><span style="width:${a.metricsStale?0:a.diskUsed}%;background:#a4bb98"></span></div></div></div><div class="panel-body"><p class="period-note">容量与可用 inode 按宿主机文件系统采集</p></div></section><section class="panel"><div class="panel-head"><h2>需要复查</h2>${button('只读诊断','host-task','pulse','small-btn',`data-id="${a.id}"`)}</div><div class="panel-body"><p class="small" style="line-height:1.9;color:#7e8e74">${a.vulnerabilities} 项软件包风险 · ${a.baselineFailed} 项基线不通过 · ${a.baselineUnknown} 项无法确认</p><div class="state-box" style="margin-top:13px">证据先行，AI 分析尚未接入。只读诊断可整理 CPU、进程、端口与配置上下文。</div></div></section></div>`;
    }else if(state.hostTab==='inventory'){
      body=`<div class="detail-grid"><section class="panel"><div class="panel-head"><h2>主机信息</h2></div><div class="properties">${property('主机名称',esc(a.name))}${property('管理分组',esc(a.group))}${property('操作系统',esc(a.os))}${property('CPU 架构',a.arch)}${property('内核版本',a.os.includes('24.04')?'6.8.0-51-generic':'5.15.0-130-generic')}${property('CPU / 内存',`${a.cores} vCPU / ${a.memoryTotal} GiB`)}${property('主网卡',`eth0 · <span class="mono">${a.ip}</span>`)}${property('部署方式','VM · Docker 特权容器')}${property('资产标签',a.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join(''))}</div></section><section class="panel"><div class="panel-head"><h2>身份与关联</h2>${pill('独立身份','green')}</div><div class="properties single">${property('稳定资产 ID',`<span class="mono">${a.id}</span>`)}${property('安装身份',`<span class="mono">install-${a.id.slice(6)}-generation-1</span>`)}${property('当前实例',`<span class="mono">instance-${a.id.slice(6)}-epoch-2</span>`)}${property('机器指纹','应用专用派生摘要 · 演示值')}${property('身份说明','IP、主机名和指纹不作为认证凭证，克隆冲突不自动合并资产。')}</div></section></div>`;
    }else if(state.hostTab==='ports')body=renderPorts(a);
    else if(state.hostTab==='packages'){const list=D.findings.filter(f=>f.assetId===a.id&&f.kind==='vulnerability');body=`<div class="notice">${icon('info')}清单来自宿主机 dpkg 数据库 · ${a.packageCount} 个已安装包 · 清单 ${shortDate(a.packageSnapshotAt)}${a.packageSnapshotStale?'（已过期，保留旧结果）':''} / 情报评估 10/21 10:42 · 未知来源不计为安全</div><section class="panel"><div class="panel-head"><h2>软件包漏洞评估</h2>${button('重新采集','host-task','refresh','small-btn',`data-id="${a.id}" data-kind="packages"`)}</div>${findingTable(list)}</section><div class="notice warning" style="margin-top:18px">${icon('info')}演示漏洞编号和版本关系仅用于展示交互。软件包更新不直接证明运行中的服务已加载新代码。</div>`;}
    else if(state.hostTab==='baseline')body=`<div class="notice warning">${icon('info')}现有密码强度未验证。此页检查 SSH / PAM 配置，不采集密码或密码散列。</div><section class="panel"><div class="panel-head"><h2>主机基线结果</h2>${button('复查基线','host-task','refresh','small-btn',`data-id="${a.id}" data-kind="baseline"`)}</div>${D.baselineRules.map((r,i)=>`<div class="rule-card"><div class="rule-title"><span class="rule-icon">${icon('checklist')}</span><div><h3>${esc(r.title)}</h3><span class="mono muted" style="font-size:10px">${r.ruleKey} · 磁盘配置视图</span></div></div><div class="flex">${verdictPill(a.baselineStates[i])}<button class="link" data-action="rule-detail" data-id="${r.ruleKey}" data-asset="${a.id}">查看依据 ${icon('chevron')}</button></div></div>`).join('')}</section>`;
    else if(state.hostTab==='tasks')body=`<section class="panel"><div class="panel-head"><h2>此主机的任务记录</h2>${button('发起检查','host-task','plus','small-btn',`data-id="${a.id}"`)}</div>${taskTable(D.tasks.filter(t=>t.assetId===a.id))}</section>`;
    return `<a href="#/assets" class="link" style="margin-bottom:17px">${icon('left')}返回主机资产</a><div class="page-heading"><div class="host-title"><span class="host-icon">${icon('server')}</span><div><div class="flex wrap"><h1>${esc(a.name)}</h1>${statusPill(a.status)}</div><p><span class="mono">${a.ip}</span> · ${a.os} · ${a.group}</p></div></div><div class="heading-actions">${button('发起只读检查','host-task','pulse','primary',`data-id="${a.id}"`)}</div></div>${scopebar()}${a.metricsStale?'<div class="notice warning">'+icon('clock')+'当前数据已过期，以下保留最近完整结果。缺测指标以“—”表示，已有风险不会自动关闭。</div>':''}<div class="tabs" role="tablist" aria-label="主机详情">${tabs.map(([v,l])=>`<button class="tab ${state.hostTab===v?'active':''}" role="tab" aria-selected="${state.hostTab===v}" data-action="host-tab" data-value="${v}">${l}</button>`).join('')}</div>${body}`;
  }
  function portRows(a){const base=[['tcp','0.0.0.0',22,'sshd',false],['tcp','0.0.0.0',443,'nginx',false],['tcp','127.0.0.1',5432,'postgres',true],['tcp','127.0.0.53',53,'systemd-resolved',true],['udp','0.0.0.0',5353,'avahi-daemon',false],['tcp','::',8080,'api-service',false],['tcp','::1',631,'cupsd',true],['udp','127.0.0.53',53,'systemd-resolved',true]];return Array.from({length:a.ports},(_,i)=>i<base.length?base[i]:['tcp','0.0.0.0',9000+i,'app-service',false]);}
  function renderPorts(a){const all=portRows(a),rows=all.filter(p=>(!state.hideLoopback||!p[4])&&(state.portType==='all'||p[0]===state.portType));return `<div class="notice">${icon('info')}TCP 监听、UDP 绑定与 Docker 发布映射分别统计。本地端点不代表已验证外网可达。</div><section class="panel"><div class="filter-toolbar"><div class="flex"><h2>宿主机端点 <span class="pill gray">${rows.length} / ${all.length}</span></h2><select class="select" id="port-type" aria-label="端口协议">${[['all','全部协议'],['tcp','TCP 监听'],['udp','UDP 绑定']].map(([v,l])=>`<option value="${v}" ${state.portType===v?'selected':''}>${l}</option>`).join('')}</select></div><label class="check-label"><input type="checkbox" id="hide-loopback" ${state.hideLoopback?'checked':''}>隐藏回环地址（127/8、::1）</label></div><div class="table-wrap"><table><thead><tr><th>协议 / 状态</th><th>监听地址</th><th>端口</th><th>关联进程</th><th>命名空间</th></tr></thead><tbody>${rows.map(([p,addr,port,proc])=>`<tr><td>${pill(p.toUpperCase(),p==='tcp'?'green':'blue')}<span style="margin-left:8px">${p==='tcp'?'监听':'绑定'}</span></td><td class="mono">${addr}</td><td class="mono">${port}</td><td>${proc}</td><td>宿主机</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">当前筛选下没有端点</div></td></tr>'}</tbody></table></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Docker 发布映射 <span class="pill gray">2</span></h2></div><div class="table-wrap"><table><thead><tr><th>容器</th><th>宿主发布地址</th><th>目标端口</th><th>协议</th></tr></thead><tbody><tr><td>business-api</td><td class="mono">0.0.0.0:8080</td><td class="mono">3000</td><td>TCP</td></tr><tr><td>metrics-exporter</td><td class="mono">127.0.0.1:9100</td><td class="mono">9100</td><td>TCP</td></tr></tbody></table></div></section>`;}
  function findingTable(list){return `<div class="table-wrap"><table><thead><tr><th>风险 / 软件包</th><th>等级</th><th>影响主机</th><th>技术状态</th><th>人工处置</th><th>最近评估</th><th></th></tr></thead><tbody>${list.map(f=>`<tr><td><button class="link" data-action="finding-detail" data-id="${f.id}" style="font-weight:550;font-size:12px;text-align:left">${esc(f.title)}</button><div class="host-sub">${esc(f.cve||f.rule)} · ${esc(f.package||'SSH / PAM')}</div></td><td>${severityPill(f.severity)}</td><td><a href="#/assets/${f.assetId}" class="host-name">${esc(asset(f.assetId)?.name)}</a><div class="host-sub">${asset(f.assetId)?.os}</div></td><td>${pill(({present:'仍存在',resolved:'已解决',unknown:'无法评估'})[f.technicalState],({present:'red',resolved:'green',unknown:'amber'})[f.technicalState])}</td><td>${pill(({open:'待处理',acknowledged:'已确认',accepted_risk:'已接受风险',false_positive:'标记误报'})[f.disposition]||f.disposition,'gray')}</td><td class="muted">${time(f.lastSeen)}</td><td><button class="icon-button" data-action="finding-detail" data-id="${f.id}" aria-label="查看风险依据">${icon('chevron')}</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">'+icon('shield')+'<h3>当前筛选下没有风险记录</h3><p>无记录不代表检查已完成，请同时查看覆盖状态。</p></div></td></tr>'}</tbody></table></div>`;}
  function renderVulnerabilities(){const all=scopedFindings('vulnerability');const list=all.filter(f=>(state.findingState==='all'||f.technicalState===state.findingState)&&(state.findingSeverity==='all'||f.severity===state.findingSeverity)&&[f.title,f.cve,f.package,asset(f.assetId)?.name].join(' ').toLowerCase().includes(state.findingSearch.toLowerCase()));return `${pageHeading(button('导出风险','export-findings','download')+button('发起复查','new-task','refresh','primary','data-kind="packages"'))}${scopebar()}<div class="stat-grid">${statCard('当前软件包风险',all.filter(f=>f.technicalState==='present').length,'bug','受影响软件包 · 逐项追踪')}${statCard('严重与高危',all.filter(f=>f.technicalState==='present'&&f.severity!=='medium').length,'alert','优先安排修复与验证')}${statCard('影响主机',new Set(all.filter(f=>f.technicalState==='present').map(f=>f.assetId)).size,'server','按稳定资产身份去重')}${statCard('无法评估',all.filter(f=>f.technicalState==='unknown').length,'info','来源或适用范围尚待确认')}</div><section class="panel"><div class="filter-toolbar"><div class="flex"><label class="search-box">${icon('search')}<input id="finding-search" aria-label="搜索漏洞" placeholder="搜索漏洞、软件包或主机" value="${esc(state.findingSearch)}"></label><select class="select" id="finding-state" aria-label="漏洞技术状态">${[['present','当前仍存在'],['unknown','无法评估'],['resolved','已解决'],['all','全部状态']].map(([v,l])=>`<option value="${v}" ${state.findingState===v?'selected':''}>${l}</option>`).join('')}</select><select class="select" id="finding-severity" aria-label="漏洞严重等级">${[['all','全部等级'],['critical','严重'],['high','高危'],['medium','中危']].map(([v,l])=>`<option value="${v}" ${state.findingSeverity===v?'selected':''}>${l}</option>`).join('')}</select></div><span class="muted small">${list.length} 项结果</span></div>${findingTable(list)}</section><div class="notice" style="margin-top:18px">${icon('info')}全部漏洞编号与匹配结果均为虚构示例。实际评估需使用 Ubuntu 情报和完整 Debian 软件包版本。</div>`;}
  function renderBaseline(){const list=scopedAssets(),count=(i,s)=>list.filter(a=>a.baselineStates[i]===s).length,total=list.length*D.baselineRules.length,pass=list.reduce((n,a)=>n+a.baselineStates.filter(s=>s==='pass').length,0),failed=list.reduce((n,a)=>n+a.baselineFailed,0),unknown=list.reduce((n,a)=>n+a.baselineUnknown,0);return `${pageHeading(button('复查基线','new-task','refresh','primary','data-kind="baseline"'))}${scopebar()}<div class="notice warning">${icon('info')}<div><strong>现有密码强度未验证。</strong> 检查覆盖 SSH 与 PAM 配置，不读取密码或密码散列；磁盘配置与运行中生效情况分别确认。</div></div><div class="stat-grid">${statCard('基线检查项',D.baselineRules.length,'checklist',`覆盖 ${number(list.length)} 台主机`)}${statCard('通过比例',`${(pass/(total||1)*100).toFixed(1)}<span class="unit">%</span>`,'shield',`${number(pass)} 项通过 / ${number(total)} 项应检查`)}${statCard('不通过',failed,'alert','需要复查配置和适用上下文')}${statCard('无法确认',number(unknown),'info','缺少证据不等于检查通过')}</div><section class="panel"><div class="panel-head"><h2>SSH 与认证配置规则</h2><span class="muted small">按当前管理组统计</span></div>${D.baselineRules.map((r,i)=>`<div class="rule-card"><div class="rule-title"><span class="rule-icon">${icon('checklist')}</span><div><h3>${esc(r.title)}</h3><span class="mono muted" style="font-size:10px">${r.ruleKey}</span></div></div><div class="rule-score"><span class="green">${number(count(i,'pass'))} 通过</span><span class="red">${count(i,'fail')} 不通过</span><span class="amber">${count(i,'unknown')} 未知</span><button class="link" data-action="rule-detail" data-id="${r.ruleKey}" aria-label="查看${r.title}">${icon('chevron')}</button></div></div>`).join('')}</section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>需要关注的基线风险</h2></div>${findingTable(scopedFindings('baseline').filter(f=>f.technicalState!=='resolved'))}</section>`;}
  function taskTable(list){return `<div class="table-wrap"><table><thead><tr><th>任务名称 / ID</th><th>目标主机</th><th>执行状态</th><th>进度</th><th>创建时间</th><th></th></tr></thead><tbody>${list.map(t=>`<tr><td><button class="link" style="font-size:12px;font-weight:550" data-action="task-detail" data-id="${t.id}">${esc(t.name)}</button><div class="host-sub">${t.id}</div></td><td><a class="host-name" href="#/assets/${t.assetId}">${esc(asset(t.assetId)?.name)}</a></td><td>${taskPill(t.state)}</td><td><div class="mini-meter"><div class="meter-track" style="width:65px"><div class="meter-fill" style="width:${t.progress}%;${t.state==='failed'?'background:#c58c7d':''}"></div></div>${t.state==='unknown'?'待确认':t.progress+'%'}</div></td><td class="muted">${shortDate(t.createdAt)}</td><td><button class="link" data-action="task-detail" data-id="${t.id}">详情 ${icon('chevron')}</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">'+icon('pulse')+'<h3>暂无匹配的任务</h3><p>发起一次只读检查，查看任务与证据的关联方式。</p></div></td></tr>'}</tbody></table></div>`;}
  function renderTasks(){const ids=new Set(scopedAssets().map(a=>a.id)),all=D.tasks.filter(t=>ids.has(t.assetId)),list=all.filter(t=>state.taskState==='all'||t.state===state.taskState);return `${pageHeading(button('新建诊断任务','new-task','plus','primary'))}${scopebar()}<div class="notice blue">${icon('spark')}结构化证据已纳入原型流程，AI 分析尚未接入。新建任务仅在当前页面模拟，刷新后恢复初始数据。</div><div class="substats"><span><strong>${all.filter(t=>['queued','running'].includes(t.state)).length}</strong> 进行中</span><span><strong>${all.filter(t=>t.state==='succeeded').length}</strong> 已完成</span><span><strong>${all.filter(t=>['failed','unknown','cancel_requested'].includes(t.state)).length}</strong> 需要关注</span></div><section class="panel"><div class="filter-toolbar"><h2>任务记录</h2><select class="select" id="task-state" aria-label="任务状态筛选">${[['all','全部状态'],['queued','待执行'],['running','执行中'],['succeeded','已完成'],['failed','失败'],['unknown','结果待确认']].map(([v,l])=>`<option value="${v}" ${state.taskState===v?'selected':''}>${l}</option>`).join('')}</select></div>${taskTable(list)}</section>`;}
  function renderPolicies(){const policies=D.policies.filter(p=>state.group==='all'||p.scope==='全局默认'||p.scope.includes(state.group)||(p.id==='policy-edge'&&state.group==='边缘节点'));return `${pageHeading(button('查看继承关系','policy-inheritance','folder'))}${scopebar()}<div class="notice">${icon('info')}策略优先级：默认 → 管理组 → 资产，选中一份完整配置。标签用于筛选，不参与权限或策略继承。</div><div class="cards-3">${policies.map(p=>`<section class="panel policy-card"><div class="flex between"><span class="rule-icon">${icon('sliders')}</span>${pill('已发布','green')}</div><div><h2>${esc(p.name)}</h2><p class="muted small" style="margin-top:8px;line-height:1.9">${esc(p.description)}</p></div><div class="policy-meta">${property('适用范围',esc(p.scope))}${property('策略修订',`r${p.revision}`)}${property('覆盖资产',`${number(p.assetCount)} 台`)}${property('最近发布',shortDate(p.updatedAt))}</div>${button('查看与调整','policy-detail','sliders','small-btn',`data-id="${p.id}"`)}</section>`).join('')}</div><div class="panel" style="margin-top:22px"><div class="panel-head"><h2>策略生效过程</h2><span class="muted small">目标与实际状态分开追踪</span></div><div class="panel-body"><div class="upgrade-stages">${['发布新修订','生成资产目标','Scout 应用','确认完整收敛'].map((l,i)=>`<div class="upgrade-stage ${i<2?'done':i===2?'current':''}"><span class="stage-circle">${i<2?icon('check'):i+1}</span>${l}</div>`).join('')}</div><p class="period-note">原型只保存当前页的策略修订，不下发真实配置。主机换组需要审查资产级覆盖并重新生成目标。</p></div></div>`;}
  function renderUpgrades(){const list=scopedAssets(),current=list.filter(a=>a.version==='0.9.0').length,ids=new Set(list.map(a=>a.id)),tasks=D.tasks.filter(t=>t.kind==='upgrade'&&ids.has(t.assetId));return `${pageHeading(button('创建灰度批次','new-upgrade','plus','primary'))}${scopebar()}<div class="stat-grid">${statCard('目标发布版本','0.9.0','upload','灰度通道 · 演示发布')}${statCard('已运行目标版本',current,'check',`当前范围占比 ${(current/(list.length||1)*100).toFixed(1)}%`)}${statCard('待升级主机',list.length-current,'server','先做平台与协议兼容性检查')}${statCard('结果待确认',tasks.filter(t=>t.state==='unknown').length,'info','暂停重复派发，先确认执行状态')}</div><div class="detail-grid"><section class="panel"><div class="panel-head"><h2>发布版本</h2><span class="muted small">签名制品与固定摘要</span></div><div class="panel-body">${D.releases.map(r=>`<div class="resource-row" style="padding-inline:0"><div class="stack"><strong class="mono">Scout ${r.version} ${pill(r.channel,r.channel==='灰度'?'amber':'green')}</strong><span class="small muted">${esc(r.description)}</span></div><button class="link" data-action="release-detail" data-id="${r.version}">兼容信息 ${icon('chevron')}</button></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>升级保护</h2>${pill('内置交接','green')}</div><div class="properties single">${property('灰度并发','按批次限制，同时保留观察窗口')}${property('结果未知','同一主机保持升级互斥，不自动重试')}${property('恢复边界','旧实例可运行时支持回退；提交后失去所有实例需外部恢复')}</div></section></div><section class="panel"><div class="panel-head"><h2>升级任务</h2><a class="link" href="#/tasks">全部任务 ${icon('arrow')}</a></div>${taskTable(tasks)}</section><div class="notice warning" style="margin-top:20px">${icon('info')}升级批次仅用于交互演示。候选启动、交接、观察与最终提交是不同阶段，开始运行不等于升级成功。</div>`;}
  function renderLogs(){return `${pageHeading()}${scopebar()}<section class="panel planning-panel"><div class="planning-icon">${icon('logs')}</div>${pill('后续能力 · 尚未接入','gray')}<h2>跨主机的安全事件，在这里连接</h2><p>围绕来源 IP、账号与事件类型，检索 SSH 认证、sudo 与关键服务事件。日志采集范围与交付阶段仍待确定。</p><div class="planning-features"><span class="flex">${icon('network')}跨主机检索</span><span class="flex">${icon('clock')}事件时间线</span><span class="flex">${icon('shield')}分组访问控制</span></div><div class="notice" style="margin-top:28px;margin-bottom:0;max-width:620px;text-align:left">${icon('info')}当前没有真实日志连接。可以先通过主机详情与只读诊断查看证据组织方式。</div><a href="#/tasks" class="btn" style="margin-top:20px">查看诊断任务 ${icon('arrow')}</a></section>`;}
  function showOverlay(title,body,footer='',{drawer=false,large=false}={}){
    if(!state.modal){returnFocus=document.activeElement;}state.modal=true;
    $('#overlay-root').innerHTML=`<div class="overlay ${drawer?'drawer-overlay':''}" data-overlay-backdrop><section class="${drawer?'drawer':`modal ${large?'large':''}`}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-header"><h2 id="dialog-title">${title}</h2><button type="button" class="icon-button" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div><div class="${drawer?'drawer-body':'modal-body'}">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;
    document.body.style.overflow='hidden';requestAnimationFrame(()=>{const control=$('.overlay input:not([type=checkbox]),.overlay select,.overlay textarea')||$('.overlay button');control?.focus();});
  }
  function closeOverlay(){if(!state.modal)return;state.modal=null;$('#overlay-root').innerHTML='';document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus();else $('#main-content').focus({preventScroll:true});}
  function newTask(ids=[],kind='diagnostic'){
    state.formAssets=ids.length?ids:[state.hostId||scopedAssets()[0]?.id].filter(Boolean);
    const options=[['diagnostic','CPU / 进程专项诊断'],['memory','内存与文件系统诊断'],['inventory','资产信息采集'],['packages','软件包清单复查'],['ports','端口清单复查'],['baseline','SSH / PAM 基线复查']];
    showOverlay('发起只读检查',`<div class="notice blue">${icon('info')}演示任务，仅在当前页面模拟。检查不修改系统配置，不执行任意命令。</div><div class="form-field"><label for="task-asset">目标主机</label>${state.formAssets.length>1?`<div class="state-box">已选 ${state.formAssets.length} 台主机：${state.formAssets.slice(0,3).map(id=>esc(asset(id)?.name)).join('、')}${state.formAssets.length>3?'…':''}</div>`:`<select id="task-asset">${scopedAssets().map(a=>`<option value="${a.id}" ${a.id===state.formAssets[0]?'selected':''}>${esc(a.name)} · ${a.ip}</option>`).join('')}</select>`}</div><div class="form-field"><label for="task-kind">检查类型</label><select id="task-kind">${options.map(([v,l])=>`<option value="${v}" ${kind===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="form-grid"><div class="form-field"><label for="task-timeout">超时限制</label><select id="task-timeout"><option value="60">60 秒</option><option value="120" selected>120 秒</option><option value="300">300 秒</option></select></div><div class="form-field"><label for="task-budget">资源预算</label><select id="task-budget"><option>低 · 保护业务负载</option><option>标准 · 常规检查</option></select></div></div><div class="state-box">返回内容：采集时间、范围、版本、脱敏证据与覆盖限制。<br>AI 模型未接入，不生成自动分析结论。</div><div id="form-error" class="form-error" role="alert"></div>`,button('取消','close-modal')+button('创建演示任务','submit-task','plus','primary'));
  }
  function showFinding(id){const f=D.findings.find(f=>f.id===id);if(!f)return;const a=asset(f.assetId);showOverlay('风险详情',`<div class="flex wrap">${severityPill(f.severity)}${pill(f.technicalState==='present'?'技术风险仍存在':f.technicalState==='resolved'?'已解决':'无法评估',f.technicalState==='present'?'red':f.technicalState==='resolved'?'green':'amber')}</div><h2 style="font-size:20px;line-height:1.6;margin-top:16px">${esc(f.title)}</h2><p class="mono muted" style="margin-top:8px">${esc(f.cve||f.rule)}</p><div class="properties">${property('影响主机',`<a href="#/assets/${a.id}" class="link" data-action="close-navigate">${a.name}</a>`)}${property('发行版 / 架构',`${a.os} / ${a.arch}`)}${property('当前软件包版本',esc(f.installedVersion||'配置规则'))}${property('适用修复版本',esc(f.fixedVersion||'按规则建议复查'))}${property('清单采集时间',`${shortDate(a.packageSnapshotAt)}${a.packageSnapshotStale?' · <span class="amber">已过期</span>':''}`)}${property('情报评估时间',`10/21 ${time(f.lastSeen)}`)}${property('人工处置',esc(({open:'待处理',acknowledged:'已确认',accepted_risk:'已接受风险',false_positive:'标记误报'})[f.disposition]))}${property('首次发现',shortDate(f.firstSeen))}</div><h3>判断依据</h3><p class="small muted" style="line-height:1.9">${esc(f.summary)}</p><div class="code-evidence">${esc(typeof f.evidence==='string'?f.evidence:JSON.stringify(f.evidence,null,2))}</div><h3>处理建议</h3><p class="small muted" style="line-height:1.9">核对适用范围与完整版本，在既有变更流程中安排修复，再发起只读复查确认。界面操作不会安装软件或修改主机。</p><div class="notice warning" style="margin-top:19px">${icon('info')}接受风险只改变人工处置，不会将技术状态标记为已修复。示例漏洞与版本关系均为虚构。</div><div class="drawer-actions">${button('发起复查','finding-rescan','refresh','primary',`data-id="${f.id}"`)}${f.disposition==='open'?button('确认风险','ack-finding','check','',`data-id="${f.id}"`):''}${f.disposition!=='accepted_risk'&&f.technicalState==='present'?button('接受风险','accept-finding','', '',`data-id="${f.id}"`):''}</div>`, '', {drawer:true});}
  function showRule(key,assetId){const r=D.baselineRules.find(r=>r.ruleKey===key);if(!r)return;const a=asset(assetId||scopedAssets()[0]?.id),index=D.baselineRules.indexOf(r);showOverlay('基线规则与证据',`${pill(r.ruleKey,'gray')}<h2 style="font-size:20px;margin-top:15px;line-height:1.6">${esc(r.title)}</h2><p class="muted small" style="line-height:1.9;margin-top:13px">${esc(r.note)}</p><div class="properties">${property('当前示例主机',a?`<a class="link" href="#/assets/${a.id}" data-action="close-navigate">${esc(a.name)}</a>`:'—')}${property('判定结果',a?verdictPill(a.baselineStates[index]):'—')}${property('配置视图','磁盘配置')}${property('运行中生效情况',pill('尚未确认','amber'))}${property('规则上下文','默认配置 + Match 例外')}${property('规则修订','r3 · 演示规则')}</div><h3>脱敏证据示例</h3><div class="code-evidence">${esc(key==='SSH-PASSWORD'?`PasswordAuthentication ${a?.baselineStates[index]==='pass'?'no':a?.baselineStates[index]==='fail'?'yes':'未获取'}\nInclude /etc/ssh/sshd_config.d/*.conf\n本条上下文：默认配置；Match 例外需独立检查\n运行参数与服务重载状态：未确认`:key.startsWith('PAM')?'PAM 质量策略：已读取配置\n规则适用范围：本地认证策略\n例外账户覆盖：待确认\n现有密码强度：未验证':'规则检查完成度：请结合主机结果\n配置包含关系：已解析\n有效运行参数：尚未确认\n证据内容：演示摘要，不含凭证')}</div><div class="notice warning" style="margin-top:20px">${icon('info')}现有密码强度未验证。未知、执行错误和不适用分别表达，不能显示为通过。</div>${a?button('在此主机复查','host-task','refresh','primary',`data-id="${a.id}" data-kind="baseline"`):''}`, '', {drawer:true});}
  function showTask(id){const t=D.tasks.find(t=>t.id===id);if(!t)return;const a=asset(t.assetId),upgrade=t.kind==='upgrade';const stage=t.state==='queued'?0:t.state==='succeeded'?3:t.state==='running'?1:2;const phase=t.state==='queued'?-1:t.state==='succeeded'?5:t.phaseIndex??(t.state==='unknown'?2:0);showOverlay(upgrade?'升级任务详情':'只读检查任务',`<div class="flex between">${taskPill(t.state)}<span class="mono muted">${t.id}</span></div><h2 style="font-size:20px;margin:17px 0;line-height:1.6">${esc(t.name)}</h2><div class="properties">${property('目标主机',`<a class="link" href="#/assets/${a.id}" data-action="close-navigate">${a.name}</a>`)}${property('创建时间',shortDate(t.createdAt))}${property('执行尝试','attempt-1 · 重投复用同一 ID')}${property('任务范围',upgrade?'签名版本升级 · 灰度批次':'限定类型的只读采集')}${property('超时 / 资源',`${t.timeout||120} 秒 / ${esc(t.budget||'低资源预算')}`)}${property('运行环境','演示 · 无真实主机连接')}</div>${upgrade?`<div class="upgrade-stages">${['预检','候选启动','交接','观察','提交'].map((s,i)=>`<div class="upgrade-stage ${i<phase?'done':i===phase?'current':''}"><span class="stage-circle">${i<phase?icon('check'):i+1}</span>${s}</div>`).join('')}</div>`:`<div class="timeline">${['任务已创建','Scout 接收并开始检查','整理脱敏证据与覆盖状态','结果已归档'].map((s,i)=>`<div class="timeline-item ${i<=stage?'done':''}">${s}<p>${i<=stage?(i===stage&&t.state==='failed'?'采集失败，保留已有完整结果':i===stage&&t.state==='unknown'?'执行结果未知，等待确认':'演示执行记录'):'等待前序阶段完成'}</p></div>`).join('')}</div>`}${t.state==='unknown'?`<div class="notice warning">${icon('alert')}执行结果未知。不能把失联当作失败重新派发，也不能声称已回退；先恢复连接并确认持久执行状态。</div>`:''}${t.state==='cancel_requested'?`<div class="notice warning">${icon('clock')}已请求取消，等待远端确认。请求发出不代表任务已经停止。</div>`:''}${t.state==='failed'?`<div class="notice warning">${icon('alert')}${esc(t.detail||'采集读取失败，旧结果仍保留。')}</div>`:''}${t.state==='succeeded'?`<div class="state-box">${upgrade?'演示交接观察已完成，提交状态已记录。':'证据包已整理：范围、采集时间、结果摘要、覆盖限制。AI 分析未接入；完成任务不自动关闭既有风险。'}</div>`:''}<div class="drawer-actions">${['queued','running'].includes(t.state)?button('模拟下一阶段','advance-task','arrow','primary',`data-id="${t.id}"`):''}${['queued','running'].includes(t.state)?button('请求取消','cancel-task','', '',`data-id="${t.id}"`):''}${t.state==='unknown'?button('查看恢复说明','recovery-info','info'):''}${t.state==='succeeded'?button('导出证据摘要','export-task','download','',`data-id="${t.id}"`):''}</div><p class="period-note">页面按钮仅推进虚构状态，刷新后恢复初始演示。</p>`, '', {drawer:true});}
  function newUpgrade(){showOverlay('创建灰度升级批次',`<div class="notice">${icon('upload')}先选择兼容的主机，再分批观察。此次仅创建页面内的演示任务。</div><div class="form-field"><label for="upgrade-version">目标版本</label><select id="upgrade-version">${D.releases.map(r=>`<option value="${r.version}">Scout ${r.version} · ${r.channel}</option>`).join('')}</select></div><div class="form-field"><label for="upgrade-group">目标管理组</label><select id="upgrade-group">${D.groups.map(g=>`<option ${state.group===g?'selected':''}>${g}</option>`).join('')}</select></div><div class="form-grid"><div class="form-field"><label for="upgrade-size">首批主机数</label><select id="upgrade-size"><option value="5">5 台</option><option value="10">10 台</option><option value="20">20 台</option></select></div><div class="form-field"><label for="upgrade-window">观察窗口</label><select id="upgrade-window"><option value="300">5 分钟</option><option value="900">15 分钟</option></select></div></div><div class="state-box">预检：操作系统与架构、制品签名、协议兼容、资源空间。<br>结果未知或已有未终结升级的主机将跳过，不重复派发。</div><label class="check-label" style="margin-top:17px"><input id="upgrade-confirm" type="checkbox">我已了解此操作只模拟灰度流程，不连接实际主机。</label><div id="form-error" class="form-error" role="alert"></div>`,button('取消','close-modal')+button('创建演示批次','submit-upgrade','upload','primary'));
  }
  function showPolicy(id){const p=D.policies.find(p=>p.id===id);if(!p)return;showOverlay('采集策略 · '+esc(p.name),`<div class="notice">${icon('info')}编辑会创建新的演示修订，不修改历史或下发真实配置。</div><div class="form-field"><label for="policy-scope">适用范围</label><input id="policy-scope" value="${esc(p.scope)}" readonly></div><div class="form-grid"><div class="form-field"><label for="policy-sampling">指标采样间隔</label><select id="policy-sampling">${[15,30,60].map(n=>`<option value="${n}" ${(p.sampling||60)===n?'selected':''}>${n} 秒</option>`).join('')}</select><small>演示配置，正式频率仍需压测。</small></div><div class="form-field"><label for="policy-baseline">基线检查周期</label><select id="policy-baseline">${[6,12,24].map(n=>`<option value="${n}" ${(p.interval||24)===n?'selected':''}>每 ${n} 小时</option>`).join('')}</select></div></div><div class="state-box">分钟指标保留 7 天 · 小时指标保留 90 天<br>检查模式：只读；额外内容采集：关闭</div><div class="form-field" style="margin-top:17px"><label for="policy-reason">修订说明</label><textarea id="policy-reason" placeholder="说明这次采集频率调整的原因" maxlength="300"></textarea></div><div id="form-error" class="form-error" role="alert"></div>`,button('取消','close-modal')+button(`发布演示修订 r${p.revision+1}`,'save-policy','check','primary',`data-id="${p.id}"`));}
  function downloadJSON(name,data){const blob=new Blob([JSON.stringify({prototype:true,notice:'虚构演示数据，不代表实际检测结果',exportedAt:D.snapshotAt,...data},null,2)],{type:'application/json;charset=utf-8'});const href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);notify('已导出演示数据');}
  function render(){renderShell();let content;if(state.page==='assets'&&state.hostId)content=renderHost();else content=({overview:renderOverview,assets:renderAssets,vulnerabilities:renderVulnerabilities,baseline:renderBaseline,tasks:renderTasks,policies:renderPolicies,upgrades:renderUpgrades,logs:renderLogs})[state.page]();$('#main-content').innerHTML=content;document.title=`${state.hostId&&state.page==='assets'?asset(state.hostId)?.name||'主机详情':headings[state.page][0]} · Sentinel Hub`;if(state.page==='assets'&&!state.hostId){const boxes=$$('.row-select');const head=$('#select-page');if(head){head.checked=boxes.length>0&&boxes.every(b=>b.checked);head.indeterminate=boxes.some(b=>b.checked)&&!head.checked;}}}
  function route(){$('#sidebar').classList.remove('open');const parts=location.hash.replace(/^#\/?/,'').split('/');const next=Object.hasOwn(headings,parts[0])?parts[0]:'overview';const host=next==='assets'&&parts[1]?decodeURIComponent(parts[1]):null;if(host!==state.hostId)state.hostTab='overview';state.page=next;state.hostId=host;closeOverlay();render();window.scrollTo(0,0);}
  function inputRender(id){const field=$('#'+id),position=field?.selectionStart;render();const target=$('#'+id);target?.focus();if(position!==null&&position!==undefined)target?.setSelectionRange(position,position);}
  document.addEventListener('input',e=>{if(e.target.id==='asset-search'){state.search=e.target.value;state.assetPage=1;inputRender('asset-search');}if(e.target.id==='finding-search'){state.findingSearch=e.target.value;inputRender('finding-search');}});
  document.addEventListener('change',e=>{
    const el=e.target;
    if(el.id==='global-group'){state.group=el.value;state.assetPage=1;state.selected.clear();if(state.hostId&&state.group!=='all'&&asset(state.hostId)?.group!==state.group){location.hash='#/assets';return;}render();}
    else if(el.id==='time-range'){state.range=el.value;render();}
    else if(el.id==='asset-status'){state.status=el.value;state.assetPage=1;render();}
    else if(el.id==='asset-risk'){state.risk=el.value;state.assetPage=1;render();}
    else if(el.id==='asset-sort'){state.sort=el.value;render();}
    else if(el.id==='finding-state'){state.findingState=el.value;render();}
    else if(el.id==='finding-severity'){state.findingSeverity=el.value;render();}
    else if(el.id==='task-state'){state.taskState=el.value;render();}
    else if(el.id==='port-type'){state.portType=el.value;render();}
    else if(el.id==='hide-loopback'){state.hideLoopback=el.checked;render();}
    else if(el.classList.contains('row-select')){el.checked?state.selected.add(el.value):state.selected.delete(el.value);render();}
    else if(el.id==='select-page'){$$('.row-select').forEach(b=>el.checked?state.selected.add(b.value):state.selected.delete(b.value));render();}
  });
  document.addEventListener('submit',e=>{if(e.target.id==='global-search-form'){e.preventDefault();state.search=$('#global-search').value.trim();state.status='all';state.risk='all';state.tags=[];state.assetPage=1;if(location.hash==='#/assets')render();else location.hash='#/assets';}});
  document.addEventListener('click',async e=>{
    if(e.target.matches('[data-overlay-backdrop]')){closeOverlay();return;}
    const el=e.target.closest('[data-action]');if(!el)return;const {action,id,value,kind}=el.dataset;
    if(action==='close-modal'||action==='close-navigate'){closeOverlay();return;}
    if(action==='menu'){$('#sidebar').classList.toggle('open');el.setAttribute('aria-expanded',String($('#sidebar').classList.contains('open')));return;}
    if(action==='new-task'){newTask([],kind||'diagnostic');return;}
    if(action==='host-task'){newTask([id],kind||'diagnostic');return;}
    if(action==='batch-task'){newTask([...state.selected]);return;}
    if(action==='clear-selection'){state.selected.clear();render();return;}
    if(action==='show-risk-assets'){state.risk='present';state.search='';state.status='all';state.tags=[];state.assetPage=1;return;}
    if(action==='page'){state.assetPage=Number(value);render();return;}
    if(action==='prev-page'||action==='next-page'){state.assetPage+=action==='prev-page'?-1:1;render();return;}
    if(action==='clear-filters'){state.search='';state.status='all';state.risk='all';state.tags=[];state.assetPage=1;render();return;}
    if(action==='tag-filter'){state.tags=state.tags.includes(value)?state.tags.filter(t=>t!==value):[...state.tags,value];state.assetPage=1;render();return;}
    if(action==='host-tab'){state.hostTab=value;render();return;}
    if(action==='metric-tab'){state.metric=value;render();return;}
    if(action==='finding-detail'){showFinding(id);return;}
    if(action==='rule-detail'){showRule(id,el.dataset.asset);return;}
    if(action==='finding-rescan'){const f=D.findings.find(f=>f.id===id);newTask([f.assetId],f.kind==='baseline'?'baseline':'packages');return;}
    if(action==='ack-finding'){const f=D.findings.find(f=>f.id===id);f.disposition='acknowledged';render();showFinding(id);notify('已确认此演示风险；技术状态保持不变');return;}
    if(action==='accept-finding'){showOverlay('接受风险',`<div class="notice warning">${icon('alert')}只改变人工处置，风险仍然存在。正式系统需要访问授权、审计和到期复查。</div><div class="form-field"><label for="accept-reason">接受原因</label><textarea id="accept-reason" maxlength="300" placeholder="填写业务原因与计划复查时间"></textarea></div><div id="form-error" class="form-error" role="alert"></div>`,button('取消','close-modal')+button('保存演示处置','save-accept','check','primary',`data-id="${id}"`));return;}
    if(action==='save-accept'){const reason=$('#accept-reason').value.trim();if(!reason){$('#form-error').textContent='请填写接受风险的原因。';return;}const f=D.findings.find(f=>f.id===id);f.disposition='accepted_risk';f.dispositionReason=reason;render();showFinding(id);notify('已接受演示风险；仍计入未修复风险');return;}
    if(action==='task-detail'){showTask(id);return;}
    if(action==='advance-task'){const t=D.tasks.find(t=>t.id===id);if(!['queued','running'].includes(t.state))return;if(t.kind==='upgrade'){t.phaseIndex=t.state==='queued'?0:(t.phaseIndex??0)+1;t.state=t.phaseIndex>=4?'succeeded':'running';t.progress=t.state==='succeeded'?100:10+t.phaseIndex*23;if(t.state==='succeeded'&&t.targetVersion)asset(t.assetId).version=t.targetVersion;}else{t.state=t.state==='queued'?'running':'succeeded';t.progress=t.state==='running'?56:100;}render();showTask(id);notify('已推进演示阶段，未执行真实主机操作');return;}
    if(action==='cancel-task'){const t=D.tasks.find(t=>t.id===id);t.state='cancel_requested';render();showTask(id);notify('已模拟请求取消；仍需等待执行端确认');return;}
    if(action==='submit-task'){
      const ids=$('#task-asset')?[$('#task-asset').value]:state.formAssets,kind=$('#task-kind').value,label=$('#task-kind').selectedOptions[0].text,timeout=Number($('#task-timeout').value),budget=$('#task-budget').value;
      if(!ids.length){$('#form-error').textContent='请选择至少一台目标主机。';return;}
      ids.forEach((assetId,i)=>D.tasks.unshift({id:`task-demo-${String(2000+state.version++).padStart(4,'0')}`,assetId,name:label,kind:kind==='memory'?'diagnostic':kind,state:'queued',createdAt:D.snapshotAt,progress:0,timeout,budget}));state.selected.clear();state.taskState='all';closeOverlay();if(location.hash==='#/tasks')render();else location.hash='#/tasks';notify(`已创建 ${ids.length} 个演示任务，可在详情中模拟执行阶段`);return;
    }
    if(action==='new-upgrade'){newUpgrade();return;}
    if(action==='submit-upgrade'){
      if(!$('#upgrade-confirm').checked){$('#form-error').textContent='请勾选演示操作确认。';return;}
      const version=$('#upgrade-version').value,group=$('#upgrade-group').value,size=Number($('#upgrade-size').value),windowSeconds=Number($('#upgrade-window').value);const open=new Set(D.tasks.filter(t=>t.kind==='upgrade'&&['queued','running','unknown','cancel_requested'].includes(t.state)).map(t=>t.assetId));
      const targets=D.assets.filter(a=>a.group===group&&a.version!==version&&a.status==='online'&&!open.has(a.id)).slice(0,size);
      if(!targets.length){$('#form-error').textContent='此管理组没有可升级的在线主机，或全部已有未终结任务。';return;}
      targets.forEach(a=>D.tasks.unshift({id:`upgrade-demo-${2000+state.version++}`,assetId:a.id,name:`Scout ${version} 灰度升级`,kind:'upgrade',state:'queued',progress:0,createdAt:D.snapshotAt,observationSeconds:windowSeconds,targetVersion:version}));state.group=group;closeOverlay();render();notify(`已创建 ${targets.length} 台主机的演示批次；跳过离线与未决升级`);return;
    }
    if(action==='release-detail'){const r=D.releases.find(r=>r.version===id);showOverlay(`Scout ${esc(r.version)} · 兼容信息`,`<div class="notice">${icon('shield')}演示制品信息，不包含真实镜像地址或部署凭证。</div><div class="properties single">${property('发布通道',r.channel)}${property('支持平台',r.compatible.map(esc).join('<br>'))}${property('制品验证','固定镜像摘要 + 签名验证')}${property('兼容性检查','协议版本、本地状态格式、挂载与资源空间')}${property('发布说明',esc(r.description))}</div>`,button('关闭','close-modal'));return;}
    if(action==='policy-detail'){showPolicy(id);return;}
    if(action==='save-policy'){const reason=$('#policy-reason').value.trim();if(!reason){$('#form-error').textContent='请填写修订说明。';return;}const p=D.policies.find(p=>p.id===id);p.sampling=Number($('#policy-sampling').value);p.interval=Number($('#policy-baseline').value);p.revision++;p.updatedAt=D.snapshotAt;p.reason=reason;p.description=`指标采样 ${p.sampling} 秒；基线每 ${p.interval} 小时；检查模式只读。`;closeOverlay();render();notify(`已发布演示修订 r${p.revision}；未下发真实策略`);return;}
    if(action==='export-overview'){downloadJSON('sentinel-overview-demo.json',{assets:scopedAssets().length,online:scopedAssets().filter(a=>a.status==='online').length,findings:scopedFindings().filter(f=>f.technicalState==='present')});return;}
    if(action==='export-assets'){downloadJSON('sentinel-assets-demo.json',{assets:filteredAssets().map(({cpuHistory,memoryHistory,...a})=>a)});return;}
    if(action==='export-findings'){downloadJSON('sentinel-findings-demo.json',{findings:scopedFindings('vulnerability')});return;}
    if(action==='export-task'){downloadJSON(`${id}-demo.json`,{task:D.tasks.find(t=>t.id===id),aiAnalysis:'not_connected',evidence:{scope:'只读限定采集',coverage:'演示结果；不代表真实检查'}});return;}
    if(action==='notifications'){showOverlay('最近动态',`<div class="activity-list" style="padding:0">${D.activity.map(a=>`<div class="activity-row"><span class="activity-icon">${icon(a.type==='warning'?'alert':'check')}</span><div><p>${esc(a.title)}</p><small>${esc(a.description)}</small></div><time>${a.time}</time></div>`).join('')}</div><p class="period-note">此处显示演示快照中的动态。</p>`,button('关闭','close-modal'));return;}
    if(action==='enroll'){showOverlay('添加主机',`<div class="notice blue">${icon('info')}原型不创建注册凭证或运行安装命令，以下展示接入步骤。</div><div class="timeline"><div class="timeline-item done">选择管理分组<p>每台主机归属一个管理分组，可添加多个筛选标签。</p></div><div class="timeline-item">获取受限登记凭证<p>正式系统限制有效期与用途，凭证不出现在日志中。</p></div><div class="timeline-item">部署 Scout 容器<p>Ubuntu 22.04 / 24.04，持久化身份并按所需能力挂载宿主视图。</p></div><div class="timeline-item">确认身份与首次完整采集<p>冲突需核查，不凭指纹自动合并。</p></div></div>`,button('了解','close-modal'));return;}
    if(action==='risk-info'){notify('统计当前仍存在的漏洞和基线风险；已接受风险也保留，未知单独展示。');return;}
    if(action==='policy-inheritance'){showOverlay('策略继承关系',`<div class="timeline"><div class="timeline-item done">全局默认策略<p>没有更具体绑定时，采用完整默认配置。</p></div><div class="timeline-item done">管理组策略<p>按主机唯一管理组选择完整配置。</p></div><div class="timeline-item done">资产级策略<p>优先级最高；换组时需要审查是否保留该覆盖。</p></div></div><div class="notice">${icon('info')}不进行隐式字段合并。标签不授予权限，也不参与策略继承。</div>`,button('了解','close-modal'));return;}
    if(action==='recovery-info'){showOverlay('升级结果待确认',`<div class="notice warning">${icon('alert')}未知结果仍占用该主机的升级名额，不允许直接重复派发。</div><p class="small muted" style="line-height:2">先检查连接和主机本地持久升级记录，确认旧实例、候选实例与活动锁状态。旧实例仍可运行时可按原状态机回退；提交后失去所有可运行实例时需要外部恢复。此原型不会执行恢复动作。</p>`,button('关闭','close-modal'));return;}
    if(action==='about'){showOverlay('关于这个交互原型',`<div class="flex" style="margin-bottom:18px"><span class="brand-mark">${icon('shield')}</span><h2 style="font-size:22px">Sentinel Hub</h2>${pill('原型 v0.1','green')}</div><p class="small muted" style="line-height:2">基于已确认的一期需求制作，包含 1,248 台虚构 Ubuntu 主机。页面交互在浏览器内运行，刷新会恢复演示数据。</p><div class="properties single" style="padding:20px 0 0">${property('可以体验','筛选主机 → 查看详情与端口 → 阅读风险证据 → 创建只读任务 → 模拟任务阶段。')}${property('其他流程','接受风险、发布策略修订、创建灰度升级批次、导出演示数据。')}${property('交付边界','AI 与日志尚未接入；恶意文件检测在第二期；本页没有真实扫描或自动处置。')}</div>`,button('开始体验','close-modal','arrow','primary'));return;}
  });
  document.addEventListener('keydown',e=>{
    if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search')?.focus();}
    if(e.key==='Escape'){if(state.modal)closeOverlay();$('#sidebar').classList.remove('open');}
    if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)&&e.target.matches('[role=tab]')){e.preventDefault();const tabs=$$('[role=tab]'),current=tabs.indexOf(e.target);const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(current+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;state.hostTab=tabs[next].dataset.value;render();$('[role=tab][aria-selected=true]')?.focus();}
    if(e.key==='Tab'&&state.modal){const nodes=$$('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled)',$('#overlay-root'));if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
  });
  window.addEventListener('hashchange',route);
  if(!location.hash)location.hash='#/overview';
  route();
})();
